import { defineRailway, github, project, service } from "railway/iac";

// Infrastructure as Code for the braintube-mcp Railway project (replaces railway.toml,
// which Railway stops reading on 2026-12-01). Generated by `railway config migrate`,
// then edited:
// - Named partial "braintube-mcp": this file owns only the resources it declares, so
//   services it does not list are left alone instead of deleted.
// - Only the braintube-mcp service is managed here. braintube-discord-bot is deployed
//   from its own code with `railway up` (Railpack, `node src/index.js`, no healthcheck);
//   the generated file wrongly gave it this repo's settings, so it stays unmanaged.
// - restartPolicy (ON_FAILURE x3) and the Dockerfile builder are carried over from
//   railway.toml explicitly; migrate dropped them.
// - Variables are unmanaged: IaC never reads or writes them (this repo is public).
export const partial = "braintube-mcp";

export default defineRailway(() => {
  const braintubeMcp = service("braintube-mcp", {
    source: github("lildaddyo/braintube-mcp", { branch: "master", checkSuites: true }),
    build: {
      builder: "DOCKERFILE",
      dockerfilePath: "Dockerfile",
    },
    deploy: {
      startCommand: "node dist/index.js",
      healthcheckPath: "/health",
      healthcheckTimeout: 10,
      restartPolicyType: "ON_FAILURE",
      restartPolicyMaxRetries: 3,
      // SIGTERM -> SIGKILL window; the server drains in-flight requests for up to 25 s (src/lib/shutdown.ts).
      drainingSeconds: 30,
      // Keep the old container serving until the new one passes /health, so a deploy has no gap.
      overlapSeconds: 20,
    },
    replicas: { "us-east4-eqdc4a": 1 },
    domains: ["mcp.brain-tube.com"],
  });

  return project("braintube-mcp", {
    variables: { managed: false },
    resources: [braintubeMcp],
  });
});
